/**
 * @minecraft/server-ui 2.0.0 の最小スタブ（テスト用）。
 *
 * 実際にフォームを描画する代わりに、組み立てた内容を shownForms に記録し、
 * テスト側が仕込んだ応答（queueResponse）を返す。
 * 応答を仕込んでいない場合は canceled: true を返す。
 */

/** 表示されたフォームの履歴。{ kind, title, body, buttons, fields } */
export const shownForms = [];

const responses = [];

/** 次に show() が返す応答を積む。 */
export function queueResponse(response) {
  responses.push(response);
}

export function resetForms() {
  shownForms.length = 0;
  responses.length = 0;
}

class BaseForm {
  constructor(kind) {
    this.kind = kind;
    this._title = undefined;
    this._body = undefined;
    this.buttons = [];
    this.fields = [];
  }
  title(v) {
    this._title = v;
    return this;
  }
  body(v) {
    this._body = v;
    return this;
  }
  show(player) {
    shownForms.push({
      kind: this.kind,
      title: this._title,
      body: this._body,
      buttons: [...this.buttons],
      fields: [...this.fields],
      playerId: player?.id,
    });
    const res = responses.shift();
    return Promise.resolve(res ?? { canceled: true, cancelationReason: "UserClosed" });
  }
}

export class ActionFormData extends BaseForm {
  constructor() {
    super("action");
  }
  button(text, icon) {
    this.buttons.push({ text, icon });
    return this;
  }
}

export class ModalFormData extends BaseForm {
  constructor() {
    super("modal");
  }
  textField(label, placeholder, options) {
    this.fields.push({ type: "text", label, placeholder, options });
    return this;
  }
  dropdown(label, options, config) {
    this.fields.push({ type: "dropdown", label, options, config });
    return this;
  }
  toggle(label, config) {
    this.fields.push({ type: "toggle", label, config });
    return this;
  }
  slider(label, min, max, config) {
    this.fields.push({ type: "slider", label, min, max, config });
    return this;
  }
  submitButton(text) {
    this._submit = text;
    return this;
  }
}

export const FormCancelationReason = {
  UserBusy: "UserBusy",
  UserClosed: "UserClosed",
};
